self.KB_CONTENT["card:756495"]={"id":"card:756495","ty":"card","sourceId":"756495","title":"『產品-客戶分類分析表』的作業重點有哪些？","ver":"iGP","topic":"分析表","keywords":["分析表","銷貨","客戶","產品"],"y":"explain","answer":"1.排序方式：可選擇「1.產品+客戶分類」或「2.客戶分類+產品」。2.相關公式：銷貨淨額 ＝ 銷貨金額－銷退金額－折讓金額銷貨毛利 ＝ 銷貨淨額－銷貨成本－壞帳金額毛利率% ＝ (銷貨毛利 /銷貨淨額)×100%觀念與「客戶-產品分析表」同。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
