self.KB_CONTENT["card:784737"]={"id":"card:784737","ty":"card","sourceId":"784737","title":"『資產改良建立作業』中的『原幣改良成本 (TC047)』為何？","ver":"GP4以上","topic":"資產","keywords":["資產","稅額","原幣"],"y":"other","answer":"* 需作原幣金額取位。* 計算原/本幣未稅金額、稅額。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
