self.KB_CONTENT["card:750307"]={"id":"card:750307","ty":"card","sourceId":"750307","title":"『進退貨單與應付憑單匯率差異表』中的『選擇排序』為何？","ver":"iGP","topic":"應付憑單","keywords":["應付憑單","貨單","單號","退貨"],"y":"other","answer":"* 計1.應付憑單單號及2.進退貨單號兩種排序方式。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
