self.KB_CONTENT["field:879682"]={"id":"field:879682","ty":"field","sourceId":"879682","title":"發票號碼","ver":"GP4.0.19.0以上","topic":"","keywords":[],"job":"銷貨單建立作業","code":"","answer":"查看PHSI23『每月發票建立作業』的【發票聯式】(TAX.MB3I0) =『PHSI16*銷貨單』【發票聯式】(COP.TG3J3) 需為\"0其它\" 若要建立發票本，請使用PHSI23『每月發票建立作業』，不要使用TAXI02。","file":"fields.jsonl"};
